$('reset-text').onclick=()=>{if(busy||dragTarget==='image')return;checkpoint();const s=current(),reset=dragTarget==='caption'?{textX:50,textY:s.type==='photo'?91:82}:dragTarget==='name'?{nameX:0,nameY:0}:{dateX:0,dateY:0};commitSettings(validateSettings({...s,...reset}));refresh();};
