function canvasPoint(e,s){const rect=canvas.getBoundingClientRect(),d=dimensions(s,!cropped),b=cropped?0:s.bleed;return{x:(e.clientX-rect.left)/rect.width*d.width-b,y:(e.clientY-rect.top)/rect.height*d.height-b};}
