async function addFiles(files){if(busy)return;const allowed=[...files].filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type));if(!allowed.length){toast('请选择 PNG、JPG 或 WebP 图片');return;}if(assets.length+allowed.length>20){toast('每个项目最多放入 20 张素材');return;}checkpoint();let count=0;for(const file of allowed){try{if(file.size>20*1024*1024)throw Error(`${file.name} 超过 20 MB`);const src=await fileData(file),img=await imageFrom(src);if(img.width*img.height>40000000)throw Error(`${file.name} 像素过大，请先缩小图片`);const asset={id:crypto.randomUUID(),name:file.name,src,img,transform:{scale:100,rotation:0,x:0,y:0}};assets.push(asset);activeId=asset.id;count++;}catch(e){toast(e.message);}}activeSetId=null;settings=baseSettings;renderAssets();presetOptions();refresh();if(count)toast(`已放入 ${count} 张素材`);$('image-input').value='';}
