function cropMarks(ctx,s,x,y,px){const left=x+s.bleed,right=left+s.width,top=y+s.bleed,bottom=top+s.height;ctx.save();ctx.strokeStyle='#666';ctx.lineWidth=.15*px;ctx.beginPath();const gap=.6,len=Math.min(2.2,Math.max(0,s.bleed-gap));if(len>0)for(const[cx,cy,dx,dy]of[[left,top,-1,-1],[right,top,1,-1],[left,bottom,-1,1],[right,bottom,1,1]]){ctx.moveTo((cx+dx*gap)*px,cy*px);ctx.lineTo((cx+dx*(gap+len))*px,cy*px);ctx.moveTo(cx*px,(cy+dy*gap)*px);ctx.lineTo(cx*px,(cy+dy*(gap+len))*px);}ctx.stroke();if(s.type==='badge'){ctx.strokeStyle='#ccc';ctx.setLineDash([px*.8,px*.8]);ctx.beginPath();ctx.ellipse((left+s.width/2)*px,(top+s.height/2)*px,s.width/2*px,s.height/2*px,0,0,Math.PI*2);ctx.stroke();}ctx.restore();}
async function sheetPdf(s,designs){const jobs=designs.flatMap(a=>Array.from({length:s.quantity},()=>a)),layout=layoutSheet(s,jobs.length);if(layout.pages>100)throw Error('拼版页数超过 100 页，请减少数量');const pw=mmToPx(layout.paperWidth,s.dpi),ph=mmToPx(layout.paperHeight,s.dpi);if(pw*ph>24000000)throw Error('纸张像素过大，请降低 DPI 或减小纸张');const d=dimensions(s),pages=[];for(let page=0;page<layout.pages;page++){const sheet=document.createElement('canvas');sheet.width=pw;sheet.height=ph;const sc=sheet.getContext('2d');sc.fillStyle='#fff';sc.fillRect(0,0,pw,ph);const px=s.dpi/25.4;for(let i=0;i<jobs.length;i++){const pos=layout.positions[i];if(pos.page!==page)continue;const a=jobs[i],design=createCanvas(a.settings,a.img);sc.drawImage(design,pos.x*px,pos.y*px,d.width*px,d.height*px);cropMarks(sc,s,pos.x,pos.y,px);}pages.push({width:pw,height:ph,bytes:new Uint8Array(await(await blobFromCanvas(sheet,'image/jpeg')).arrayBuffer())});await new Promise(r=>setTimeout(r,0));}return{blob:makePdf(pages,layout.paperWidth,layout.paperHeight),pages:layout.pages};}
$('export-pdf').onclick=()=>exporting(async()=>{const s={...current()},designs=activeSetId?[{img:selected().img,settings:s}]:assets.map(a=>({img:a.img,settings:{...s,...a.transform}})),pdf=await sheetPdf(s,designs);download(pdf.blob,`谷子工坊_${TYPE_NAMES[s.type]}_拼版_${pdf.pages}页.pdf`);});
function setPreview(items){const c=document.createElement('canvas');c.width=1600;c.height=1000;const pc=c.getContext('2d');pc.fillStyle='#e8edf0';pc.fillRect(0,0,1600,1000);pc.textAlign='center';pc.fillStyle='#253a38';pc.font='700 36px system-ui,sans-serif';pc.fillText(items[0].settings.characterName||'我的谷子套组',800,85);items.forEach((item,i)=>{const a=assets.find(a=>a.id===item.assetId),art=createCanvas({...item.settings,dpi:150},a.img,{crop:true}),ratio=Math.min(390/art.width,660/art.height),w=art.width*ratio,h=art.height*ratio;pc.save();pc.translate(285+i*515,480);pc.rotate((i-1)*.04);pc.shadowColor='#233c4040';pc.shadowBlur=22;pc.shadowOffsetY=18;pc.drawImage(art,-w/2,-h/2,w,h);pc.restore();pc.fillStyle='#536c69';pc.font='24px system-ui,sans-serif';pc.fillText(`${TYPE_NAMES[item.settings.type]} · ${item.settings.width} × ${item.settings.height} mm`,285+i*515,895);});pc.fillStyle='#788a87';pc.font='18px system-ui,sans-serif';pc.fillText('谷子工坊 / 整套效果示意',800,958);return c;}
$('export-set').onclick=()=>exporting(async()=>{const items=currentSet().map(i=>({...i,settings:{...i.settings}}));if(items.length!==3)throw Error('请先生成完整的三款谷子');const files=[];for(let i=0;i<items.length;i++){const item=items[i],a=assets.find(a=>a.id===item.assetId),s=validateSettings(item.settings),name=`${String(i+1).padStart(2,'0')}_${TYPE_NAMES[s.type]}_${s.width}x${s.height}mm`;files.push({name:`${name}_${s.dpi}dpi.png`,data:await pngBytes(createCanvas(s,a.img),s.dpi)});const pdf=await sheetPdf(s,[{img:a.img,settings:s}]);files.push({name:`${name}_拼版.pdf`,data:new Uint8Array(await pdf.blob.arrayBuffer())});}files.push({name:'整套预览_非制作稿.png',data:new Uint8Array(await(await blobFromCanvas(setPreview(items))).arrayBuffer())});files.push({name:'制作参数.json',data:new TextEncoder().encode(JSON.stringify({format:'guzi-set',version:1,units:'mm',colorSpace:'RGB',items:items.map(i=>({name:TYPE_NAMES[i.settings.type],settings:i.settings})),printNote:'PDF 请按实际大小 100% 打印。制作前请确认厂家出血、白墨及颜色要求。'},null,2))});download(makeZip(files),`${baseName(items[0].settings.characterName||selected().name)}_谷子整套.zip`);});
$('save-project').onclick=()=>{download(new Blob([JSON.stringify(serialize())],{type:'application/json'}),'我的谷子.guzi');toast('项目已下载，包含图片和编辑参数');};
$('load-project').onclick=()=>$('project-input').click();
async function restore(data){if(data?.format!=='guzi-workshop'||![1,2].includes(data.version)||!Array.isArray(data.assets)||data.assets.length>20)throw Error('不是有效的谷子工坊项目文件');const next=validateSettings(data.settings),loaded=[];for(const a of data.assets){if(typeof a.name!=='string'||typeof a.id!=='string'||typeof a.src!=='string'||a.src.length>30000000||!/^data:image\/(png|jpeg|webp);base64,/.test(a.src))throw Error('项目图片格式无效');const s=validateSettings({...next,...a.transform});const img=await imageFrom(a.src);if(img.width*img.height>40000000)throw Error('项目中的图片过大');if(loaded.some(x=>x.id===a.id))throw Error('项目素材标识重复');loaded.push({id:a.id,name:a.name.slice(0,150),src:a.src,img,transform:Object.fromEntries(transforms.map(k=>[k,s[k]]))});}const collection=[];if(data.version===2){if(!Array.isArray(data.setItems)||data.setItems.length>60)throw Error('整套项目数据无效');for(const item of data.setItems){if(typeof item.id!=='string'||typeof item.assetId!=='string'||!loaded.some(a=>a.id===item.assetId)||collection.some(i=>i.id===item.id))throw Error('整套素材引用无效');const s=validateSettings(item.settings);if(collection.some(i=>i.assetId===item.assetId&&i.settings.type===s.type))throw Error('整套中的谷子类型重复');collection.push({id:item.id,assetId:item.assetId,settings:s});}for(const a of loaded){const count=collection.filter(i=>i.assetId===a.id).length;if(count!==0&&count!==3)throw Error('整套必须包含完整的三款谷子');}}baseSettings=next;settings=next;assets=loaded;setItems=collection;activeId=assets.find(a=>a.id===data.activeId)?.id??assets[0]?.id??null;const active=collection.find(i=>i.id===data.activeSetId);activeSetId=active?.id??null;if(active){activeId=active.assetId;settings=active.settings;}presetOptions();renderAssets();refresh();}
$('project-input').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100*1024*1024)throw Error('项目文件超过 100 MB');const data=JSON.parse(await file.text());checkpoint();await restore(data);toast('项目已打开');}catch(e){toast(e.message||'项目读取失败');}finally{$('project-input').value='';}};
$('undo').onclick=async()=>{if(!undoStack.length)return;const data=JSON.parse(undoStack.pop());await restore(data);$('undo').disabled=!undoStack.length;};
$('new-project').onclick=()=>{if(busy)return;if(assets.length&&!confirm('新建项目将清空当前工作台。需要保留的话，请先保存项目文件。'))return;checkpoint();settings=defaults();baseSettings=settings;assets=[];activeId=null;setItems=[];activeSetId=null;mock=false;cropped=false;dragTarget='image';presetOptions();renderAssets();refresh();toast('新的工作台已准备好');};
$('import-template').onclick=()=>$('template-input').click();
$('template-input').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('模板文件过大');const t=JSON.parse(await f.text());if(t.format!=='guzi-template'||t.version!==1)throw Error('请选择 guzi-template v1 JSON 模板，格式见项目说明');if(activeSetId&&t.type!==settings.type)throw Error('请先选择整套中对应的款式，再导入该款制作规格');const s=validateSettings({...current(),type:t.type,width:t.width,height:t.height,bleed:t.bleed,safe:t.safe});checkpoint();commitSettings(s);presetOptions();refresh();toast('制作规格已导入');}catch(e){toast(e.message);}finally{$('template-input').value='';}};
// Optional WebMCP registration uses the same actions and state as the visible UI.
const mc=document.modelContext;if(mc?.registerTool){try{
mc.registerTool({name:'read_guzi_project',title:'查看谷子制作参数',description:'读取当前谷子及整套的制作参数，不读取图片内容。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('不接受参数');const s=current();let sheet;try{sheet=layoutSheet(s,(activeSetId?1:Math.max(1,assets.length))*s.quantity);}catch(e){sheet={error:e.message};}return{settings:s,assetCount:assets.length,editingSetId:activeSetId,collection:currentSet().map(i=>({id:i.id,settings:{...i.settings}})),sheet};}});
mc.registerTool({name:'configure_guzi_dimensions',title:'调整谷子尺寸',description:'调整当前款成品宽高和出血，立即更新编辑画布，不导出文件。',inputSchema:{type:'object',properties:{width:{type:'number',minimum:10,maximum:200},height:{type:'number',minimum:10,maximum:200},bleed:{type:'number',minimum:0,maximum:10}},required:['width','height','bleed'],additionalProperties:false},execute(input){if(busy)throw Error('请等待导出完成');if(!input||Object.keys(input).some(k=>!['width','height','bleed'].includes(k))||['width','height','bleed'].some(k=>typeof input[k]!=='number'))throw Error('尺寸参数无效');const next=validateSettings({...current(),...input});checkpoint();commitSettings(next);refresh();return{width:settings.width,height:settings.height,bleed:settings.bleed};}});
}catch(e){console.warn('WebMCP unavailable',e);}}
presetOptions();syncControls();draw();renderCollection();
(async()=>{restoring=true;try{const saved=await dbAction('readonly',store=>store.get('current'));if(saved){await restore(saved);$('save-state').textContent='已恢复本地项目';}else{const r=await fetch('sample.png');if(r.ok){const src=await fileData(await r.blob()),img=await imageFrom(src);assets=[{id:crypto.randomUUID(),name:'星野 · 原创示例.png',src,img,transform:{scale:100,rotation:0,x:0,y:8}}];activeId=assets[0].id;renderAssets();syncControls();draw();}}}catch(e){console.warn(e);$('save-state').textContent='可下载项目文件保存';}finally{restoring=false;renderCollection();scheduleSave();}})();
document.fonts.ready.then(draw);
